//! Char stdlib intrinsics.
//!
//! Each intrinsic is a `fn(*CallCtx) !EvalResult`. For member access the
//! receiver is `args[0]`, with any further user arguments following.
//!
//! Char predicates follow kotlinc-native 2.3.21 semantics, driven by
//! Unicode general categories rather than ASCII shortcuts. The category
//! and case-mapping tables embedded at the bottom of this file are the
//! `unicode_general_category` 1.1.0 data and Rust's `char` case mappings.

const std = @import("std");
const runtime = @import("runtime");
const unicode_category = @import("unicode_category.zig");

const Value = runtime.Value;
const RuntimeError = runtime.RuntimeError;
const EvalResult = runtime.EvalResult;
const CallCtx = runtime.CallCtx;
const StringRef = runtime.StringRef;
const charUnitToString = runtime.charUnitToString;

fn ok(v: Value) EvalResult {
    return .{ .ok = v };
}

fn typeErr(msg: []const u8) EvalResult {
    return .{ .err = .{ .Type = msg } };
}

// ============================================================
// Char members
// ============================================================

/// `Result<u16, RuntimeError>` for receiver extraction: the receiver code
/// unit, or a typed `RuntimeError` describing the wrong/absent receiver.
const RecvChar = union(enum) {
    unit: u16,
    err: RuntimeError,
};

fn recvChar(args: []const Value, comptime what: []const u8) RecvChar {
    if (args.len == 0) {
        return .{ .err = .{ .Type = what ++ " requires a receiver" } };
    }
    return switch (args[0]) {
        .Char => |c| .{ .unit = c },
        else => .{ .err = .{ .Type = what ++ " requires a Char receiver" } },
    };
}

/// Decode a `Char` code unit to a Unicode scalar for category/case
/// queries. A lone surrogate has no scalar value (`null`): such chars are
/// not letters/digits/whitespace and have no case mapping.
pub fn charUnitToScalar(unit: u16) ?u21 {
    if (unit >= 0xD800 and unit <= 0xDFFF) return null;
    return unit;
}

pub fn char_code(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.code");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |u| ok(Value.newInt(@as(i64, u))),
    };
}

/// `Char.getCategoryValue()` — the Unicode general-category code, from the
/// compiled-in table (see `unicode_category.zig`).
pub fn char_get_category_value(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.getCategoryValue");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |u| ok(Value.newInt(@as(i64, unicode_category.categoryValue(@as(i32, u))))),
    };
}

fn imod(a: i64, b: i64) i64 {
    const m = @mod(a, b);
    return if (m >= 0) m else m + b;
}

/// `kotlin.internal.getProgressionLastElement(start, end, step)`.
///
/// Result narrows back to a Kotlin Int when the progression was Int-typed.
/// A progression step value as an i64, regardless of its int kind.
fn stepAsI64(v: Value) i64 {
    return switch (v) {
        .Int => |x| @as(i64, x),
        .Long => |x| x,
        .Short => |x| @as(i64, x),
        .Byte => |x| @as(i64, x),
        .UInt => |x| @as(i64, @as(i32, @bitCast(x))),
        .ULong => |x| @bitCast(x),
        else => 1,
    };
}
fn diffModU32(a: u32, b: u32, c: u32) u32 {
    const ac = a % c;
    const bc = b % c;
    return if (ac >= bc) ac - bc else ac -% bc +% c;
}
fn uintProgressionLast(start: u32, end: u32, step: i32) u32 {
    if (step > 0) return if (start >= end) end else end - diffModU32(end, start, @intCast(step));
    if (step < 0) return if (start <= end) end else end + diffModU32(start, end, @intCast(-step));
    return end;
}
fn diffModU64(a: u64, b: u64, c: u64) u64 {
    const ac = a % c;
    const bc = b % c;
    return if (ac >= bc) ac - bc else ac -% bc +% c;
}
fn ulongProgressionLast(start: u64, end: u64, step: i64) u64 {
    if (step > 0) return if (start >= end) end else end - diffModU64(end, start, @intCast(step));
    if (step < 0) return if (start <= end) end else end + diffModU64(start, end, @intCast(-step));
    return end;
}

pub fn internal_get_progression_last_element(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const args = ctx.args;
    if (args.len != 3) {
        return typeErr("getProgressionLastElement expects (start, end, step)");
    }
    var start: i64 = undefined;
    var end: i64 = undefined;
    var step: i64 = undefined;
    var is_long: bool = undefined;
    // Unsigned progressions use unsigned modular arithmetic (UProgressionUtil).
    if (args[0] == .UInt and args[1] == .UInt) {
        const s: u32 = args[0].UInt;
        const e: u32 = args[1].UInt;
        const st: i32 = @truncate(stepAsI64(args[2]));
        return ok(.{ .UInt = uintProgressionLast(s, e, st) });
    }
    if (args[0] == .ULong and args[1] == .ULong) {
        const s: u64 = args[0].ULong;
        const e: u64 = args[1].ULong;
        return ok(.{ .ULong = ulongProgressionLast(s, e, stepAsI64(args[2])) });
    }
    if (args[0] == .Long and args[1] == .Long and args[2] == .Long) {
        start = args[0].Long;
        end = args[1].Long;
        step = args[2].Long;
        is_long = true;
    } else if (args[0] == .Int and args[1] == .Int and args[2] == .Int) {
        start = @as(i64, args[0].Int);
        end = @as(i64, args[1].Int);
        step = @as(i64, args[2].Int);
        is_long = false;
    } else {
        return typeErr("getProgressionLastElement: args must be all Int or all Long");
    }

    var last: i64 = undefined;
    if (step > 0) {
        if (start >= end) {
            last = end;
        } else {
            const diff = imod(imod(end, step) - imod(start, step), step);
            last = end - diff;
        }
    } else if (step < 0) {
        if (start <= end) {
            last = end;
        } else {
            const neg = -step;
            const diff = imod(imod(start, neg) - imod(end, neg), neg);
            last = end + diff;
        }
    } else {
        return typeErr("Step is zero.");
    }

    return ok(if (is_long) .{ .Long = last } else Value.newInt(last));
}

// ============================================================
// Char predicates
// ============================================================

pub fn ktIsLetter(c: u21) bool {
    return rangeContains(c, &letter_table);
}

pub fn ktIsDigit(c: u21) bool {
    return rangeContains(c, &decimal_number_table);
}

// kotlinc-native 2.3.21 whitespace table (from stdlib/native-wasm
// _WhitespaceChars.kt). A fixed enumerated set -- not Java's
// Character.isWhitespace (which excludes NBSP) and not Rust's
// char::is_whitespace (which excludes 0x1C..=0x1F).
pub fn ktIsWhitespace(c: u21) bool {
    const code: u32 = c;
    return (code >= 0x0009 and code <= 0x000D) or
        (code >= 0x001C and code <= 0x0020) or
        code == 0x00A0 or
        code == 0x1680 or
        (code >= 0x2000 and code <= 0x200A) or
        code == 0x2028 or
        code == 0x2029 or
        code == 0x202F or
        code == 0x205F or
        code == 0x3000;
}

pub fn isOtherUppercase(code: u32) bool {
    return (code >= 0x2160 and code <= 0x216F) or
        (code >= 0x24B6 and code <= 0x24CF) or
        (code >= 0x1F130 and code <= 0x1F149) or
        (code >= 0x1F150 and code <= 0x1F169) or
        (code >= 0x1F170 and code <= 0x1F189);
}

// Other_Lowercase contributory property (Unicode 15.x snapshot used by
// kotlinc-native 2.3.21).
pub fn isOtherLowercase(code: u32) bool {
    const ranges = [_][2]u32{
        .{ 0x00AA, 0x00AA },
        .{ 0x00BA, 0x00BA },
        .{ 0x02B0, 0x02B8 },
        .{ 0x02C0, 0x02C1 },
        .{ 0x02E0, 0x02E4 },
        .{ 0x0345, 0x0345 },
        .{ 0x037A, 0x037A },
        .{ 0x1D2C, 0x1D6A },
        .{ 0x1D78, 0x1D78 },
        .{ 0x1D9B, 0x1DBF },
        .{ 0x2071, 0x2071 },
        .{ 0x207F, 0x207F },
        .{ 0x2090, 0x209C },
        .{ 0x2170, 0x217F },
        .{ 0x24D0, 0x24E9 },
        .{ 0x2C7C, 0x2C7D },
        .{ 0xA69C, 0xA69D },
        .{ 0xA770, 0xA770 },
        .{ 0xA7F8, 0xA7F9 },
        .{ 0xAB5C, 0xAB5F },
    };
    for (ranges) |r| {
        if (code >= r[0] and code <= r[1]) return true;
    }
    return false;
}

pub fn ktIsUpperCase(c: u21) bool {
    return rangeContains(c, &uppercase_letter_table) or isOtherUppercase(c);
}

pub fn ktIsLowerCase(c: u21) bool {
    return rangeContains(c, &lowercase_letter_table) or isOtherLowercase(c);
}

fn boolPredicate(ctx: *CallCtx, comptime what: []const u8, pred: *const fn (u21) bool) EvalResult {
    const r = recvChar(ctx.args, what);
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |u| ok(.{ .Bool = if (charUnitToScalar(u)) |c| pred(c) else false }),
    };
}

pub fn char_is_digit(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return boolPredicate(ctx, "Char.isDigit", ktIsDigit);
}

pub fn char_is_letter(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return boolPredicate(ctx, "Char.isLetter", ktIsLetter);
}

pub fn char_is_letter_or_digit(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.isLetterOrDigit");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |u| ok(.{ .Bool = if (charUnitToScalar(u)) |c| (ktIsLetter(c) or ktIsDigit(c)) else false }),
    };
}

pub fn char_is_whitespace(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return boolPredicate(ctx, "Char.isWhitespace", ktIsWhitespace);
}

pub fn char_is_uppercase(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return boolPredicate(ctx, "Char.isUpperCase", ktIsUpperCase);
}

pub fn char_is_lowercase(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return boolPredicate(ctx, "Char.isLowerCase", ktIsLowerCase);
}

/// `Char.compareTo(other)` -- the sign of the UTF-16 code-unit ordering
/// (-1 / 0 / 1), matching kotlinc and the other primitive `compareTo`
/// intrinsics.
pub fn char_compare_to(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.compareTo");
    const a = switch (r) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    if (ctx.args.len < 2 or ctx.args[1] != .Char) {
        return typeErr("Char.compareTo requires a Char");
    }
    const b = ctx.args[1].Char;
    const result: i32 = if (a < b) -1 else @intFromBool(a > b);
    return ok(.{ .Int = result });
}

/// `Char.isISOControl()` -- a C0 (`0x00..=0x1F`) or C1 (`0x7F..=0x9F`)
/// control code unit.
pub fn char_is_iso_control(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.isISOControl");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |u| ok(.{ .Bool = u <= 0x1F or (u >= 0x7F and u <= 0x9F) }),
    };
}

/// Collect the full case mapping of a scalar into an owned UTF-8 string.
fn caseString(allocator: std.mem.Allocator, c: u21, map: []const CaseEntry) std.mem.Allocator.Error![]u8 {
    if (lookupCase(c, map)) |scalars| {
        var buf: std.ArrayList(u8) = .empty;
        errdefer buf.deinit(allocator);
        for (scalars) |s| {
            var tmp: [4]u8 = undefined;
            const n = std.unicode.utf8Encode(s, &tmp) catch unreachable;
            try buf.appendSlice(allocator, tmp[0..n]);
        }
        return buf.toOwnedSlice(allocator);
    }
    // No special mapping: the scalar maps to itself.
    var tmp: [4]u8 = undefined;
    const n = std.unicode.utf8Encode(c, &tmp) catch unreachable;
    return allocator.dupe(u8, tmp[0..n]);
}

fn casedStringValue(ctx: *CallCtx, comptime what: []const u8, map: []const CaseEntry) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, what);
    const unit = switch (r) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    const s: []u8 = if (charUnitToScalar(unit)) |c|
        try caseString(ctx.allocator, c, map)
    else
        try charUnitToString(ctx.allocator, unit);
    return ok(.{ .String = try runtime.strInitOwned(ctx.allocator, s) });
}

pub fn char_uppercase(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return casedStringValue(ctx, "Char.uppercase", &uppercase_map);
}

pub fn char_lowercase(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return casedStringValue(ctx, "Char.lowercase", &lowercase_map);
}

pub fn char_to_string(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.toString");
    const unit = switch (r) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    const s = try charUnitToString(ctx.allocator, unit);
    return ok(.{ .String = try runtime.strInitOwned(ctx.allocator, s) });
}

/// `Result<u32, RuntimeError>` for the validated `digitToInt` radix.
const RadixResult = union(enum) {
    radix: u32,
    err: RuntimeError,
};

/// The radix argument of `digitToInt(radix)` / `digitToIntOrNull(radix)`,
/// validated to Kotlin's 2..36 range (default 10). Returns the radix or an
/// `IllegalArgumentException`.
fn charDigitRadix(allocator: std.mem.Allocator, args: []const Value) std.mem.Allocator.Error!RadixResult {
    const radix: i64 = if (args.len > 1) (args[1].asI64() orelse 10) else 10;
    if (radix < 2 or radix > 36) {
        const msg = try std.fmt.allocPrint(allocator, "radix {d} is not in valid range 2..36", .{radix});
        return .{ .err = .{ .Thrown = .{ .Exception = .{
            .fqn = try runtime.strInit(allocator, "kotlin.IllegalArgumentException"),
            .message = try runtime.strInitOwned(allocator, msg),
            .cause = null,
        } } } };
    }
    return .{ .radix = @intCast(radix) };
}

/// `char::to_digit(radix)`: digit value of an ASCII alphanumeric, mirroring
/// Rust's stdlib which only recognizes `0-9`, `a-z`, `A-Z`.
fn toDigit(c: u21, radix: u32) ?u32 {
    const digit: u32 = switch (c) {
        '0'...'9' => c - '0',
        'a'...'z' => c - 'a' + 10,
        'A'...'Z' => c - 'A' + 10,
        // Fullwidth forms (U+FF10.. digits, U+FF21.. upper, U+FF41.. lower).
        0xFF10...0xFF19 => c - 0xFF10,
        0xFF21...0xFF3A => c - 0xFF21 + 10,
        0xFF41...0xFF5A => c - 0xFF41 + 10,
        else => return null,
    };
    return if (digit < radix) digit else null;
}

pub fn char_digit_to_int(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.digitToInt");
    const unit = switch (r) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    const radix = switch (try charDigitRadix(ctx.allocator, ctx.args)) {
        .err => |e| return .{ .err = e },
        .radix => |v| v,
    };
    const d: ?u32 = if (charUnitToScalar(unit)) |c| toDigit(c, radix) else null;
    if (d) |value| {
        return ok(Value.newInt(@as(i64, value)));
    }
    const rendered = try charUnitToString(ctx.allocator, unit);
    defer ctx.allocator.free(rendered);
    const debug = try rustDebugString(ctx.allocator, rendered);
    defer ctx.allocator.free(debug);
    const msg = try std.fmt.allocPrint(
        ctx.allocator,
        "Char {s} is not a digit in the given radix={d}",
        .{ debug, radix },
    );
    return .{ .err = .{ .Thrown = .{ .Exception = .{
        .fqn = try runtime.strInit(ctx.allocator, "kotlin.IllegalArgumentException"),
        .message = try runtime.strInitOwned(ctx.allocator, msg),
        .cause = null,
    } } } };
}

pub fn char_digit_to_int_or_null(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.digitToIntOrNull");
    const unit = switch (r) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    const radix = switch (try charDigitRadix(ctx.allocator, ctx.args)) {
        .err => |e| return .{ .err = e },
        .radix => |v| v,
    };
    const d: ?u32 = if (charUnitToScalar(unit)) |c| toDigit(c, radix) else null;
    return ok(if (d) |value| Value.newInt(@as(i64, value)) else .Null);
}

pub fn char_is_high_surrogate(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.isHighSurrogate");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |c| ok(.{ .Bool = c >= 0xD800 and c <= 0xDBFF }),
    };
}

pub fn char_is_low_surrogate(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.isLowSurrogate");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |c| ok(.{ .Bool = c >= 0xDC00 and c <= 0xDFFF }),
    };
}

pub fn char_is_surrogate(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const r = recvChar(ctx.args, "Char.isSurrogate");
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |c| ok(.{ .Bool = c >= 0xD800 and c <= 0xDFFF }),
    };
}

/// `Char(code: Int)` / `Char(code: UShort)` constructors. The `Int` overload
/// requires `code in 0..0xFFFF` and throws `IllegalArgumentException`
/// otherwise; the unsigned overload is always in range (a `u16`-wide value).
pub fn char_ctor(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    if (ctx.args.len < 1) return typeErr("Char requires a code argument");
    switch (ctx.args[0]) {
        .UShort, .UByte, .UInt, .ULong => {
            const code = ctx.args[0].asU64() orelse 0;
            return ok(.{ .Char = @truncate(code) });
        },
        else => {
            const code = ctx.args[0].asI64() orelse return typeErr("Char requires an Int or UShort code");
            if (code < 0 or code > 0xFFFF) {
                const msg = try std.fmt.allocPrint(ctx.allocator, "Invalid Char code: {d}", .{code});
                return .{ .err = .{ .Thrown = .{ .Exception = .{
                    .fqn = try runtime.strInit(ctx.allocator, "kotlin.IllegalArgumentException"),
                    .message = try runtime.strInitOwned(ctx.allocator, msg),
                    .cause = null,
                } } } };
            }
            return ok(.{ .Char = @intCast(code) });
        },
    }
}

// ============================================================
// Additional Char
// ============================================================

/// Single-Char case mapping: Kotlin's `uppercaseChar()/lowercaseChar()`
/// return the original char when the full case mapping isn't a single
/// character (e.g. 'ß'.`uppercaseChar()` == 'ß', not 'S' -- only the
/// multi-char `uppercase()` yields "SS").
pub fn singleCaseChar(c: u21, map: []const CaseEntry) u21 {
    if (lookupCase(c, map)) |scalars| {
        if (scalars.len == 1) return scalars[0];
        return c;
    }
    return c;
}

/// `Char.equals(other, ignoreCase = true)`: equal if the upper-cased units
/// match, or failing that the lower-cased upper-cased units match (Kotlin's
/// rule, which also pairs characters that share a lowercase form).
pub fn charEqIgnoreCase(a_unit: u16, b_unit: u16) bool {
    if (a_unit == b_unit) return true;
    const a = charUnitToScalar(a_unit) orelse return false;
    const b = charUnitToScalar(b_unit) orelse return false;
    const a_up = singleCaseChar(a, &uppercase_map);
    const b_up = singleCaseChar(b, &uppercase_map);
    if (a_up == b_up) return true;
    return singleCaseChar(a_up, &lowercase_map) == singleCaseChar(b_up, &lowercase_map);
}

fn singleCasedChar(ctx: *CallCtx, comptime what: []const u8, map: []const CaseEntry) EvalResult {
    const r = recvChar(ctx.args, what);
    return switch (r) {
        .err => |e| .{ .err = e },
        .unit => |unit| ok(.{ .Char = if (charUnitToScalar(unit)) |c|
            @truncate(singleCaseChar(c, map))
        else
            unit }),
    };
}

pub fn char_uppercase_char(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    return singleCasedChar(ctx, "Char.uppercaseChar", &uppercase_map);
}

pub fn char_lowercase_char(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    // `lowercaseChar()` is the SIMPLE one-to-one mapping; where the full
    // mapping is multi-scalar Kotlin still yields a single char (İ U+0130 ->
    // 'i', not 'i' + combining dot). The full map would return the original.
    const unit = switch (recvChar(ctx.args, "Char.lowercaseChar")) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    if (charUnitToScalar(unit)) |c| {
        if (c == 0x0130) return ok(.{ .Char = 0x69 });
        return ok(.{ .Char = @truncate(singleCaseChar(c, &lowercase_map)) });
    }
    return ok(.{ .Char = unit });
}

// ============================================================
// Char title-case
// ============================================================

/// The dedicated titlecase (Lt) form of the `DŽ/LJ/NJ/DZ` digraph letters,
/// whose titlecase differs from their uppercase (e.g. `Ǆ` U+01C4 titlecases
/// to `ǅ` U+01C5, not to itself). Null for every other char (titlecase ==
/// uppercase there).
fn titlecaseSingle(c: u21) ?u21 {
    return switch (c) {
        0x01C4, 0x01C5, 0x01C6 => 0x01C5,
        0x01C7, 0x01C8, 0x01C9 => 0x01C8,
        0x01CA, 0x01CB, 0x01CC => 0x01CB,
        0x01F1, 0x01F2, 0x01F3 => 0x01F2,
        else => null,
    };
}

pub fn char_titlecase(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    const unit = switch (recvChar(ctx.args, "Char.titlecase")) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    if (charUnitToScalar(unit)) |c| {
        // A Lt digraph letter titlecases to its single title form.
        if (titlecaseSingle(c)) |t| {
            const s = try charUnitToString(ctx.allocator, @truncate(t));
            return ok(.{ .String = try runtime.strInitOwned(ctx.allocator, s) });
        }
        // Every other char: the uppercase expansion with only the first unit
        // kept upper (e.g. 'ß' -> "Ss", not "SS").
        const up = try caseString(ctx.allocator, c, &uppercase_map);
        defer ctx.allocator.free(up);
        const titled = try titlecaseFirst(ctx.allocator, up);
        return ok(.{ .String = try runtime.strInitOwned(ctx.allocator, titled) });
    }
    const s = try charUnitToString(ctx.allocator, unit);
    return ok(.{ .String = try runtime.strInitOwned(ctx.allocator, s) });
}

/// Lowercase every codepoint of `s` except the first (so an all-uppercase
/// multi-char case expansion like "SS" becomes the title form "Ss").
fn titlecaseFirst(allocator: std.mem.Allocator, s: []const u8) std.mem.Allocator.Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var view = std.unicode.Utf8View.initUnchecked(s);
    var it = view.iterator();
    var first = true;
    var buf: [4]u8 = undefined;
    while (it.nextCodepoint()) |cp| {
        const mapped: u21 = if (first) cp else singleCaseChar(cp, &lowercase_map);
        first = false;
        const n = std.unicode.utf8Encode(mapped, &buf) catch {
            const m = std.unicode.utf8Encode(cp, &buf) catch 0;
            try out.appendSlice(allocator, buf[0..m]);
            continue;
        };
        try out.appendSlice(allocator, buf[0..n]);
    }
    return out.toOwnedSlice(allocator);
}

pub fn char_titlecase_char(ctx: *CallCtx) std.mem.Allocator.Error!EvalResult {
    // The dedicated Lt title form when one exists; otherwise the uppercase
    // 1:1 mapping (and the original char when uppercase isn't single, 'ß').
    const unit = switch (recvChar(ctx.args, "Char.titlecaseChar")) {
        .err => |e| return .{ .err = e },
        .unit => |u| u,
    };
    if (charUnitToScalar(unit)) |c| {
        if (titlecaseSingle(c)) |t| return ok(.{ .Char = @truncate(t) });
        return ok(.{ .Char = @truncate(singleCaseChar(c, &uppercase_map)) });
    }
    return ok(.{ .Char = unit });
}

/// Render a UTF-8 string the way Rust's `{:?}` (`str`'s `Debug`) does:
/// wrapped in double quotes with `"`, `\`, and the C0/C1 control codes
/// escaped (`\t`/`\n`/`\r` specially, the rest as `\u{..}`). Every other
/// scalar is passed through verbatim, matching Rust for all printable
/// characters. Caller owns the returned slice.
fn rustDebugString(allocator: std.mem.Allocator, s: []const u8) std.mem.Allocator.Error![]u8 {
    var buf: std.ArrayList(u8) = .empty;
    errdefer buf.deinit(allocator);
    try buf.append(allocator, '"');
    var view = std.unicode.Utf8View.initUnchecked(s);
    var it = view.iterator();
    while (it.nextCodepoint()) |cp| {
        switch (cp) {
            '"' => try buf.appendSlice(allocator, "\\\""),
            '\\' => try buf.appendSlice(allocator, "\\\\"),
            '\t' => try buf.appendSlice(allocator, "\\t"),
            '\n' => try buf.appendSlice(allocator, "\\n"),
            '\r' => try buf.appendSlice(allocator, "\\r"),
            0x00...0x08, 0x0B, 0x0C, 0x0E...0x1F, 0x7F, 0x80...0x9F => {
                var tmp: [16]u8 = undefined;
                const esc = std.fmt.bufPrint(&tmp, "\\u{{{x}}}", .{cp}) catch unreachable;
                try buf.appendSlice(allocator, esc);
            },
            else => {
                var tmp: [4]u8 = undefined;
                const n = std.unicode.utf8Encode(@intCast(cp), &tmp) catch unreachable;
                try buf.appendSlice(allocator, tmp[0..n]);
            },
        }
    }
    try buf.append(allocator, '"');
    return buf.toOwnedSlice(allocator);
}

// ============================================================
// Unicode tables and lookup
// ============================================================

const Range = struct { u32, u32 };

const CaseEntry = struct {
    cp: u21,
    scalars: []const u21,
};

/// Binary search an ascending, non-overlapping inclusive range table.
fn rangeContains(c: u32, table: []const Range) bool {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const entry = table[mid];
        if (c < entry[0]) {
            hi = mid;
        } else if (c > entry[1]) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

/// Binary search an ascending case-mapping table keyed by code point.
fn lookupCase(c: u21, map: []const CaseEntry) ?[]const u21 {
    var lo: usize = 0;
    var hi: usize = map.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const entry = map[mid];
        if (c < entry.cp) {
            hi = mid;
        } else if (c > entry.cp) {
            lo = mid + 1;
        } else {
            return entry.scalars;
        }
    }
    return null;
}

// ============================================================
// Tests
// ============================================================

const testing = std.testing;

fn noopCtx(args: []const Value) CallCtx {
    return .{
        .args = args,
        .out = undefined,
        .host = undefined,
        .allocator = testing.allocator,
    };
}

test "code returns the code unit as an Int" {
    const args = [_]Value{.{ .Char = 'A' }};
    var ctx = noopCtx(&args);
    const r = try char_code(&ctx);
    try testing.expectEqual(@as(i32, 65), r.ok.Int);
}

test "code rejects a non-char receiver" {
    const args = [_]Value{.{ .Int = 1 }};
    var ctx = noopCtx(&args);
    const r = try char_code(&ctx);
    try testing.expect(r == .err);
    try testing.expect(r.err == .Type);
}

test "category predicates follow unicode general categories" {
    try testing.expect(ktIsLetter('A'));
    try testing.expect(ktIsLetter('z'));
    try testing.expect(ktIsLetter(0x00DF)); // ß
    try testing.expect(!ktIsLetter('5'));
    try testing.expect(ktIsDigit('7'));
    try testing.expect(!ktIsDigit('A'));
    try testing.expect(ktIsUpperCase('Q'));
    try testing.expect(!ktIsUpperCase('q'));
    try testing.expect(ktIsLowerCase('q'));
    try testing.expect(!ktIsLowerCase('Q'));
    // Roman numerals are Other_Uppercase / Other_Lowercase.
    try testing.expect(ktIsUpperCase(0x2160));
    try testing.expect(ktIsLowerCase(0x2170));
}

test "whitespace table matches kotlinc-native" {
    try testing.expect(ktIsWhitespace(' '));
    try testing.expect(ktIsWhitespace('\t'));
    try testing.expect(ktIsWhitespace(0x00A0)); // NBSP counts
    try testing.expect(ktIsWhitespace(0x001C)); // file separator counts
    try testing.expect(!ktIsWhitespace('a'));
    try testing.expect(!ktIsWhitespace(0x200B)); // zero-width space does not
}

test "isDigit/isLetter dispatch through receiver" {
    const a = [_]Value{.{ .Char = '4' }};
    var c1 = noopCtx(&a);
    try testing.expect((try char_is_digit(&c1)).ok.Bool);
    const b = [_]Value{.{ .Char = 'x' }};
    var c2 = noopCtx(&b);
    try testing.expect((try char_is_letter(&c2)).ok.Bool);
    try testing.expect(!(try char_is_digit(&c2)).ok.Bool);
}

test "lone surrogate has no category" {
    const args = [_]Value{.{ .Char = 0xD800 }};
    var ctx = noopCtx(&args);
    try testing.expect(!(try char_is_letter(&ctx)).ok.Bool);
    try testing.expect(!(try char_is_whitespace(&ctx)).ok.Bool);
}

test "compareTo returns the ordering sign" {
    const lt = [_]Value{ .{ .Char = 'a' }, .{ .Char = 'b' } };
    var c1 = noopCtx(&lt);
    try testing.expectEqual(@as(i32, -1), (try char_compare_to(&c1)).ok.Int);
    const eq = [_]Value{ .{ .Char = 'a' }, .{ .Char = 'a' } };
    var c2 = noopCtx(&eq);
    try testing.expectEqual(@as(i32, 0), (try char_compare_to(&c2)).ok.Int);
    const gt = [_]Value{ .{ .Char = 'b' }, .{ .Char = 'a' } };
    var c3 = noopCtx(&gt);
    try testing.expectEqual(@as(i32, 1), (try char_compare_to(&c3)).ok.Int);
}

test "isISOControl covers C0 and C1 ranges" {
    const c0 = [_]Value{.{ .Char = 0x0007 }};
    var a = noopCtx(&c0);
    try testing.expect((try char_is_iso_control(&a)).ok.Bool);
    const c1 = [_]Value{.{ .Char = 0x0085 }};
    var b = noopCtx(&c1);
    try testing.expect((try char_is_iso_control(&b)).ok.Bool);
    const normal = [_]Value{.{ .Char = 'A' }};
    var c = noopCtx(&normal);
    try testing.expect(!(try char_is_iso_control(&c)).ok.Bool);
}

fn expectStringResult(r: EvalResult, want: []const u8) !void {
    try testing.expect(r == .ok);
    const g = r.ok.String.borrow();
    defer {
        g.deinit();
        r.ok.String.deinit();
    }
    try testing.expectEqualStrings(want, g.get().bytes);
}

test "uppercase expands sharp-s to SS" {
    const args = [_]Value{.{ .Char = 0x00DF }}; // ß
    var ctx = noopCtx(&args);
    try expectStringResult(try char_uppercase(&ctx), "SS");
}

test "lowercase maps a single letter" {
    const args = [_]Value{.{ .Char = 'A' }};
    var ctx = noopCtx(&args);
    try expectStringResult(try char_lowercase(&ctx), "a");
}

test "toString renders the code unit" {
    const args = [_]Value{.{ .Char = 'Z' }};
    var ctx = noopCtx(&args);
    try expectStringResult(try char_to_string(&ctx), "Z");
}

test "uppercaseChar keeps sharp-s unchanged" {
    const args = [_]Value{.{ .Char = 0x00DF }}; // ß has no single-char uppercase
    var ctx = noopCtx(&args);
    const r = try char_uppercase_char(&ctx);
    try testing.expectEqual(@as(u16, 0x00DF), r.ok.Char);
}

test "uppercaseChar maps a regular letter" {
    const args = [_]Value{.{ .Char = 'a' }};
    var ctx = noopCtx(&args);
    const r = try char_uppercase_char(&ctx);
    try testing.expectEqual(@as(u16, 'A'), r.ok.Char);
}

test "lowercaseChar maps a regular letter" {
    const args = [_]Value{.{ .Char = 'A' }};
    var ctx = noopCtx(&args);
    const r = try char_lowercase_char(&ctx);
    try testing.expectEqual(@as(u16, 'a'), r.ok.Char);
}

test "lowercaseChar uses the single-char simple mapping (U+0130 -> i)" {
    // İ (U+0130) has a multi-scalar FULL lowercase, but `lowercaseChar()` yields
    // the single-char simple mapping 'i' (matching `Character.toLowerCase`).
    const args = [_]Value{.{ .Char = 0x0130 }};
    var ctx = noopCtx(&args);
    const r = try char_lowercase_char(&ctx);
    try testing.expectEqual(@as(u16, 0x69), r.ok.Char);
}

test "digitToInt parses within radix" {
    const dec = [_]Value{.{ .Char = '7' }};
    var c1 = noopCtx(&dec);
    try testing.expectEqual(@as(i32, 7), (try char_digit_to_int(&c1)).ok.Int);
    const hex = [_]Value{ .{ .Char = 'f' }, .{ .Int = 16 } };
    var c2 = noopCtx(&hex);
    try testing.expectEqual(@as(i32, 15), (try char_digit_to_int(&c2)).ok.Int);
}

test "digitToInt throws for a non-digit" {
    const args = [_]Value{.{ .Char = 'Z' }};
    var ctx = noopCtx(&args);
    const r = try char_digit_to_int(&ctx);
    try testing.expect(r == .err);
    try testing.expect(r.err == .Thrown);
    const exc = r.err.Thrown.Exception;
    {
        const mg = exc.message.?.borrow();
        defer mg.deinit();
        try testing.expectEqualStrings(
            "Char \"Z\" is not a digit in the given radix=10",
            mg.get().bytes,
        );
    }
    {
        const fg = exc.fqn.borrow();
        defer fg.deinit();
        try testing.expectEqualStrings("kotlin.IllegalArgumentException", fg.get().bytes);
    }
    exc.message.?.deinit();
    exc.fqn.deinit();
}

test "digitToInt throws for an out-of-range radix" {
    const args = [_]Value{ .{ .Char = '1' }, .{ .Int = 99 } };
    var ctx = noopCtx(&args);
    const r = try char_digit_to_int(&ctx);
    try testing.expect(r == .err);
    try testing.expect(r.err == .Thrown);
    const exc = r.err.Thrown.Exception;
    {
        const mg = exc.message.?.borrow();
        defer mg.deinit();
        try testing.expectEqualStrings("radix 99 is not in valid range 2..36", mg.get().bytes);
    }
    {
        const fg = exc.fqn.borrow();
        defer fg.deinit();
        try testing.expectEqualStrings("kotlin.IllegalArgumentException", fg.get().bytes);
    }
    exc.message.?.deinit();
    exc.fqn.deinit();
}

test "digitToIntOrNull returns null for a non-digit" {
    const args = [_]Value{.{ .Char = 'Z' }};
    var ctx = noopCtx(&args);
    const r = try char_digit_to_int_or_null(&ctx);
    try testing.expect(r == .ok);
    try testing.expect(r.ok == .Null);
    const ok_case = [_]Value{.{ .Char = '9' }};
    var c2 = noopCtx(&ok_case);
    try testing.expectEqual(@as(i32, 9), (try char_digit_to_int_or_null(&c2)).ok.Int);
}

test "surrogate predicates classify the surrogate ranges" {
    const high = [_]Value{.{ .Char = 0xD800 }};
    var c1 = noopCtx(&high);
    try testing.expect((try char_is_high_surrogate(&c1)).ok.Bool);
    try testing.expect((try char_is_surrogate(&c1)).ok.Bool);
    try testing.expect(!(try char_is_low_surrogate(&c1)).ok.Bool);
    const low = [_]Value{.{ .Char = 0xDC00 }};
    var c2 = noopCtx(&low);
    try testing.expect((try char_is_low_surrogate(&c2)).ok.Bool);
    try testing.expect((try char_is_surrogate(&c2)).ok.Bool);
    const plain = [_]Value{.{ .Char = 'a' }};
    var c3 = noopCtx(&plain);
    try testing.expect(!(try char_is_surrogate(&c3)).ok.Bool);
}

test "titlecaseChar matches uppercase for plain letters" {
    const args = [_]Value{.{ .Char = 'a' }};
    var ctx = noopCtx(&args);
    const r = try char_titlecase_char(&ctx);
    try testing.expectEqual(@as(u16, 'A'), r.ok.Char);
}

test "titlecase renders the title string" {
    const args = [_]Value{.{ .Char = 'a' }};
    var ctx = noopCtx(&args);
    try expectStringResult(try char_titlecase(&ctx), "A");
}

test "getProgressionLastElement clamps to last reachable Int" {
    const fwd = [_]Value{ .{ .Int = 1 }, .{ .Int = 10 }, .{ .Int = 2 } };
    var c1 = noopCtx(&fwd);
    const r1 = try internal_get_progression_last_element(&c1);
    try testing.expectEqual(@as(i32, 9), r1.ok.Int);

    const bwd = [_]Value{ .{ .Int = 10 }, .{ .Int = 1 }, .{ .Int = -2 } };
    var c2 = noopCtx(&bwd);
    const r2 = try internal_get_progression_last_element(&c2);
    try testing.expectEqual(@as(i32, 2), r2.ok.Int);

    const lng = [_]Value{ .{ .Long = 1 }, .{ .Long = 10 }, .{ .Long = 3 } };
    var c3 = noopCtx(&lng);
    const r3 = try internal_get_progression_last_element(&c3);
    try testing.expectEqual(@as(i64, 10), r3.ok.Long);
}

test "getProgressionLastElement rejects a zero step" {
    const args = [_]Value{ .{ .Int = 1 }, .{ .Int = 10 }, .{ .Int = 0 } };
    var ctx = noopCtx(&args);
    const r = try internal_get_progression_last_element(&ctx);
    try testing.expect(r == .err);
}


